export const GLOSSARY_SHARD = Object.freeze({"altcoin":{"slug":"altcoin","cat":"basics","en":"Altcoin","contentLocale":"zh-Hans","term":"山寨币（Altcoin）","aka":["Altcoin","竞争币","山寨"],"short":"山寨币是指比特币以外的所有加密货币，包括以太坊、Solana 等公链币，也包括各种应用代币和 Meme 币。","body":[["Altcoin 来自 alternative coin，原意是",["比特币","bitcoin"],"的替代品。中文币圈习惯叫“山寨币”，但这个词并不一定带贬义，",["市值","market-capitalization"],"很大的",["以太坊","ethereum"],"、BNB、SOL 在统计上也属于山寨币。有些人会把",["稳定币","stablecoin"],"单独拿出来，不算作山寨币。"],["山寨币之间差别巨大：有的是有大量开发者和用户的公链，有的是某个应用的代币，有的只是社区炒作的 ",["Meme 币","memecoin"],"。它们的市值、",["流动性","liquidity"],"和代币解锁计划都不同，同样跌 10% 的行情里，小市值山寨币可能跌得更多。"],"很多山寨币和比特币走势相关性较高，比特币大跌时它们往往跟跌。币圈常说的“山寨季”指资金大量从比特币流向山寨币的阶段，但这种行情的时间和幅度都无法预测。"],"example":"假设某天比特币下跌 5%，你持有的两枚山寨币分别下跌 8% 和 25%。若你各投入 1,000 USDT，前者剩 920 USDT，后者只剩 750 USDT。后者市值只有几千万美元、交易所挂单稀薄，卖出 1,000 USDT 的量还可能再产生 1% 到 2% 的滑点。","mistakes":["觉得单价便宜的山寨币“更容易翻倍”，忽略了它的流通量和总市值。","把资金全部押在一两个小市值山寨币上，没有考虑流动性风险。","不看代币解锁计划，买入后遇到大额解锁抛压。"],"faq":[{"q":"以太坊算山寨币吗？","a":"按定义算，因为它不是比特币。不过很多人会把以太坊单独看作第二大主流币，不和小币放在一起讨论。"},{"q":"山寨币一定是骗局吗？","a":"不是。“山寨币”只是比特币以外币种的统称，其中既有成熟项目也有空气币，需要逐个看项目、代币经济和流动性。"}],"title":"什么是山寨币（Altcoin）？含义与风险","description":"山寨币是什么意思、以太坊算不算山寨币、山寨币与比特币走势的关系，以及买小市值山寨币时要注意的流动性和解锁风险。","related":[["bitcoin","比特币（Bitcoin，BTC）","比特币是 2009 年上线的第一个去中心化加密货币，总量上限 2100 万枚，通过工作量证明挖矿维护网络，代号 BTC。"],["memecoin","Meme 币（Memecoin）","Meme 币是以网络梗、动物形象或社区文化为主题、通常没有明确实际用途的加密货币，价格主要由社区热度和投机驱动。"],["market-capitalization","市值（Market Cap）","市值是一个加密货币的当前价格乘以流通量得到的总价值，用来比较不同币种的规模，英文为 Market Cap。"],["token-listing","上币（Token listing）","上币是指交易所正式开放某个代币的充值和交易，为它开设现货或合约交易对，让用户可以在平台上买卖，通常会提前发布上币公告和开盘时间。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":"/coins","cta":false},"layer-2":{"slug":"layer-2","cat":"basics","en":"Layer 2 (L2)","contentLocale":"zh-Hans","term":"二层网络（Layer 2，L2）","aka":["L2","Layer 2","二层","Rollup"],"short":"二层网络（L2）是建立在一层区块链之上的扩容方案，在二层批量处理交易后把结果提交回主链，以更低的费用借用主链安全性。","body":[[["以太坊","ethereum"],"主网空间有限，拥堵时 ",["Gas 费","gas-fee"],"很高。L2 的思路是：把大量交易放在二层执行，再把压缩后的数据和结果提交到以太坊。这样一批交易分摊一次主网成本，单笔费用就低得多。Arbitrum、Optimism、Base、zkSync 都是常见的以太坊 L2。"],"主流 L2 多为 Rollup，分为乐观 Rollup 和零知识（ZK）Rollup。乐观 Rollup 默认交易有效，留出挑战期，因此通过官方桥从 L2 提回主网通常要等约 7 天；ZK Rollup 用数学证明验证，提回时间一般更短。",["L2 上的 Gas 通常仍用 ETH 支付。不同 L2 的去中心化程度、排序器是否由单一团队运营、升级权限如何设置都不一样，资金量大时值得了解。",["交易所","centralized-exchange"],"充提时要选对具体的 L2 网络。"]],"example":["假设以太坊主网上一次代币兑换要消耗 150,000 Gas，Gas 价格 30 gwei，即 0.0045 ETH；ETH 价格 3,000 ",["USDT","usdt"]," 时约 13.5 USDT。同样的兑换放到某个 L2 上，费用可能只有 0.05 到 0.2 USDT。如果你一个月操作 20 次，主网要约 270 USDT，L2 可能只要几美元。"],"mistakes":["以为 L2 上的 USDC 可以直接发到主网地址并在主网显示，实际上需要跨链。","用官方桥从乐观 Rollup 提回主网，没预料到约 7 天的等待期。","在交易所提币时把 Arbitrum 和 Optimism 搞混，选错网络。"],"faq":[{"q":"L2 上的资产安全吗？","a":"L2 借用主链安全性，但仍有桥合约、排序器和升级权限等额外风险，不同项目的成熟度不同。"},{"q":"L2 的 Gas 费用什么币付？","a":"多数以太坊 L2 使用 ETH 付 Gas，所以你需要在对应 L2 上留一点 ETH。"}],"title":"什么是 Layer 2（L2）？二层网络的含义","description":"Layer 2（二层网络）是什么？讲清 Rollup 如何降低 Gas 费、乐观 Rollup 与 ZK Rollup 的区别，以及在 L2 充提时的注意事项。","related":[["layer-1","一层网络（Layer 1，L1）","一层网络（L1）是指自己负责共识、安全和交易结算的基础区块链，比如比特币、以太坊、Solana 和 BNB Chain。"],["gas-fee","Gas 费（Gas Fee）","Gas 费是在以太坊等区块链上发送交易或调用智能合约时支付给网络的手续费，用链的原生币结算，高低取决于操作复杂度和网络拥堵。"],["cross-chain-bridge","跨链桥（Cross-chain Bridge）","跨链桥是把资产或信息从一条区块链转移到另一条区块链的协议，常见方式是在源链锁定资产、在目标链铸造等量的映射代币。"],["ethereum","以太坊（Ethereum，ETH）","以太坊是支持智能合约的开源区块链，原生币为 ETH，用于支付 Gas 费和质押，DeFi、NFT 和大量代币都运行在它上面。"],["blockchain-network","充提币网络（链的选择）","充提币网络是指充币或提币时选择的区块链，例如 USDT 可以走 TRC20、ERC20 或 BEP20 等不同网络，发送方和接收方必须选择同一条链。"]],"lesson":null,"coin":{"slug":"arbitrum","name":"Arbitrum","symbol":"ARB"},"tool":null,"cta":false},"spot-trading":{"slug":"spot-trading","cat":"trading","en":"Spot trading","contentLocale":"zh-Hans","term":"现货交易（Spot Trading）","aka":["现货","Spot","币币交易"],"short":"现货交易是以当前市场价格直接买卖加密货币并即时完成交割的交易方式，买入后你真正持有这个币。","body":[["在现货市场用 ",["USDT","usdt"]," 买入 ",["BTC","bitcoin"],"，成交后 BTC 就进入你的账户，你可以继续持有、卖出或提到钱包。这和",["合约交易","futures-contract"],"不同：合约只是押注价格涨跌，你并不持有标的资产。早期国内平台把现货叫“币币交易”。"],["现货交易没有",["强平","liquidation"],"（爆仓）风险，最坏情况是币价跌到接近零，亏损上限就是你投入的本金。这也是新手通常从现货开始的原因。现货的成本主要是手续费、",["买卖价差","bid-ask-spread"],"和",["滑点","slippage"],"。"],"下单时常用市价单和限价单：市价单立即按当前最优价格成交，限价单按你指定的价格挂单等待。部分交易所还提供现货杠杆（借币交易），那就有强平风险了，要注意区分。"],"example":"假设 SOL 现价 150 USDT，你用 600 USDT 市价买入，手续费 0.1%。实际用于买币的约 599.4 USDT，得到约 3.996 SOL。一个月后 SOL 涨到 180 USDT，你卖出得到约 719.3 USDT，再扣 0.1% 手续费约 0.72 USDT，到手约 718.6 USDT，净赚约 118.6 USDT。如果跌到 120 USDT，卖出则亏约 121 USDT，但不会被强平。","mistakes":["把现货杠杆或合约误以为是普通现货，不知道会被强平。","流动性差的币直接用大额市价单，成交价比预期差很多。","忘了计算买入和卖出两次手续费，高估了实际收益。"],"faq":[{"q":"现货和合约有什么区别？","a":"现货是直接买入并持有币，没有爆仓；合约是用保证金交易价格涨跌，可以加杠杆、可以做空，但有强平风险。"},{"q":"现货交易会亏光吗？","a":"不加杠杆的现货最多亏掉投入的本金，前提是币价跌到接近零。主流币和小币的风险程度差异很大。"}],"title":"什么是现货交易？现货的含义与新手入门","description":"现货交易是什么意思？讲清现货买币的成交和交割方式、与合约交易的区别、手续费如何计算，以及为什么现货不会爆仓。","related":[["trading-pair","交易对（Trading Pair）","交易对是指两种资产相互报价、可以直接兑换的组合，如 BTC/USDT 表示用 USDT 买卖 BTC，价格表示 1 个 BTC 值多少 USDT。"],["market-order","市价单（Market Order）","市价单是以当前市场上最优可得价格立即成交的订单，优点是成交快、几乎一定成交，缺点是无法控制成交价格。"],["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"第一笔现货：从100到0.002枚"},"coin":null,"tool":"/compare","cta":true},"candlestick-chart":{"slug":"candlestick-chart","cat":"trading","en":"Candlestick chart","contentLocale":"zh-Hans","term":"K线图（Candlestick Chart）","aka":["K线","蜡烛图","candlestick"],"short":"K线图是用一根根K线记录每个时间段开盘价、最高价、最低价和收盘价的价格图表，是加密货币交易软件中最常用的看盘方式。","body":["每根K线代表一个固定周期，比如 1 分钟、1 小时或 1 天。中间粗的部分叫实体，连接开盘价和收盘价；上下细线叫影线，上影线顶端是最高价，下影线底端是最低价。收盘价高于开盘价是阳线，反之是阴线。国内交易软件通常默认红涨绿跌，很多海外界面是绿涨红跌，可以在设置里切换。","K线的价值在于把一个时间段内多空争夺的结果压缩成一个图形。长上影线说明价格冲高后被卖压打回，长下影线说明下跌时有人在低位承接。实体很长、影线很短，说明这一周期里一方占绝对优势。",["同一段行情，周期不同，形态可能完全不同。短周期噪音多，长周期更能反映趋势。看K线时最好同时看下方的",["成交量","trading-volume"],"柱，放量的长影线比缩量的更有参考意义。"]],"example":["假设 ",["ETH","ethereum"]," 的一根 1 小时K线：开盘 3,000 ",["USDT","usdt"],"，最高 3,080，最低 2,950，收盘 3,050。收盘高于开盘，是一根阳线，实体长度 50 USDT。上影线从 3,050 到 3,080，长 30 USDT；下影线从 2,950 到 3,000，长 50 USDT。这说明这一小时里价格曾跌到 2,950，但买盘把它拉回并收在较高位置。"],"mistakes":["不看时间周期就解读形态，把 1 分钟K线的信号当成日线级别的趋势。","没注意软件的红绿配色设置，把阴线当阳线看反。","只凭一两根K线形态就重仓下单，不结合成交量和支撑阻力。"],"faq":[{"q":"K线的影线代表什么？","a":"上影线代表该周期内到达过的最高价，下影线代表最低价。影线越长，说明价格在那个方向上被打回得越多。"},{"q":"K线是红涨绿跌还是绿涨红跌？","a":"两种都有。国内用户习惯红涨绿跌，很多国际交易所默认绿涨红跌，大多数交易软件可以在设置里切换。"}],"title":"K线图怎么看？加密货币蜡烛图入门","description":"从实体、上下影线到阳线阴线，教你读懂加密货币K线图，了解不同时间周期的区别，以及如何结合成交量解读K线。","related":[["support-and-resistance","支撑位与阻力位（Support and Resistance）","支撑位是价格下跌时多次止跌反弹的价格区域，阻力位（也叫压力位）是价格上涨时多次受阻回落的区域，交易者用它们规划入场、止损和止盈。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"],["trading-volume","成交量（Trading Volume）","成交量是在一段时间内实际成交的资产数量或金额，例如 24 小时成交量，用来衡量一个币或一个市场的交易活跃程度。"],["all-time-high","历史最高价（ATH）","历史最高价（ATH，All-Time High）是某个资产自上市交易以来曾达到的最高价格，创新高即价格突破这一纪录。"]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"一根K线，到底告诉你哪四件事？"},"coin":null,"tool":null,"cta":false},"last-price":{"slug":"last-price","cat":"derivatives","en":"Last traded price","contentLocale":"zh-Hans","term":"最新价（Last Traded Price）","aka":["最新成交价","成交价","last price"],"short":"最新价是某个交易对在订单簿上最后一笔实际成交的价格，也是交易软件和K线图上默认显示的实时价格。","body":[["你在行情页看到的那个跳动的价格，大多就是最新价。它只代表最后一笔成交的价格，不代表你下一笔一定能按这个价格成交：你实际能买到的价格要看卖一，能卖出的价格要看买一，中间还有",["买卖价差","bid-ask-spread"],"和",["滑点","slippage"],"。"],["在合约市场里，最新价和",["标记价格","mark-price"],"、",["指数价格","index-price"],"是三个不同的价格。最新价最灵敏，也最容易因为一笔大单出现插针；标记价格更平滑，用于",["强平","liquidation"],"；指数价格反映多家现货市场。"],["设置止损止盈时，很多",["交易所","centralized-exchange"],"允许选择按“最新价”还是“标记价格”触发。按最新价触发更贴近实际成交，但更容易被插针扫掉；按标记价格触发更稳，但在急速行情里可能让成交价偏离预期。"]],"example":"假设你持有 ETH 多单，止损触发价设为 2,900 USDT。某一刻合约市场出现一笔大额卖单，最新价瞬间插到 2,880，而标记价格只跌到 2,950。如果止损按最新价触发，这笔止损会被执行，随后价格回到 3,000；如果按标记价格触发，止损不会被执行，仓位得以保留。两种选择没有绝对对错，要和你的策略匹配。","mistakes":["以为看到的最新价就是自己下单的成交价，忽略买卖价差和滑点。","用最新价判断离强平多远，而强平实际按标记价格判断。","设置止损时不检查触发价类型，被插针意外触发。"],"faq":[{"q":"最新价和标记价格哪个更准？","a":"两者用途不同。最新价反映该市场的真实最后成交；标记价格是为了公平计算盈亏和强平而平滑过的参考价。"},{"q":"止损应该选最新价还是标记价格触发？","a":"选最新价触发更接近实际成交，但容易被插针触发；选标记价格触发更不容易误触，但急速行情下成交价可能更远。按策略选择。"}],"title":"最新价是什么？最新成交价与标记价格区别","description":"解释交易软件里最新价（最新成交价）的含义、它与标记价格和指数价格的区别，以及设置止损时如何选择触发价格类型。","related":[["mark-price","标记价格（Mark Price）","标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。"],["index-price","指数价格（Index Price）","指数价格是交易所根据多家主流现货交易所的价格，按一定权重加权计算出的综合现货价格，用作标记价格和资金费率的基准。"],["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"],["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"屏幕上的价格，为什么不是我的成交价？"},"coin":null,"tool":null,"cta":false},"funding-rate-arbitrage":{"slug":"funding-rate-arbitrage","cat":"derivatives","en":"Funding rate arbitrage","contentLocale":"zh-Hans","term":"资金费率套利（Funding Rate Arbitrage）","aka":["资费套利","期现套利","funding arbitrage"],"short":"资金费率套利是买入现货、同时在永续合约开等量空单，保持方向中性，赚取正资金费率期间空头收到的资金费的策略。","body":[[["永续合约","perpetual-futures"],["资金费率","funding-rate"],"为正时，多头付钱给空头。如果你持有现货多头、合约空头，两边数量相等，币价涨跌对你基本没有影响，而空单每个结算周期都能收到资金费，这就是资金费率套利，也常被称为期现套利。"],["收益看起来稳定，但有几项真实风险：资金费率会变化甚至转负，转负后空单要反过来付钱；开平仓四笔交易的手续费会吃掉好几天的资金费；如果现货和合约在不同账户，币价暴涨时合约空单可能因保证金不足被",["强平","liquidation"],"，而现货的盈利救不了它。"],["部分",["交易所","centralized-exchange"],"的",["统一账户","unified-trading-account"],"或",["组合保证金模式","portfolio-margin"],"，可以让现货作为合约空单的保证金，降低强平风险。也有交易所推出了自动化的资金费套利产品，使用前要看清楚规则和费用。"]],"example":"假设你用 10,000 USDT 买入 ETH 现货，同时开 10,000 USDT 的 ETH 永续空单。资金费率稳定在 +0.01%，每 8 小时结算一次，每次收到 1 USDT，一天 3 USDT，一年约 1,095 USDT，年化约 11%。但如果现货买卖和合约开平仓手续费合计约 30 USDT，就需要先收 10 天资金费才能回本。","mistakes":["只看当前资金费率推算年化，忽略费率会下降甚至转负。","合约空单杠杆开太高，币价暴涨时空单被强平，套利变成单边亏损。","没把四笔交易的手续费和滑点算进成本。"],"faq":[{"q":"资金费率套利是无风险的吗？","a":"不是。它规避了大部分方向风险，但仍有资金费转负、空单被强平、手续费吃掉收益和交易所平台风险。"},{"q":"资金费率套利需要多少资金？","a":"没有固定门槛，但资金越少，手续费占比越高。还需要为合约空单预留足够保证金，避免价格上涨时被强平。"}],"title":"资金费率套利是什么？期现套利怎么做","description":"解释资金费率套利（期现套利）的原理，用实例算出收益和回本时间，并说明费率转负、空单强平和手续费等主要风险。","related":[["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"],["arbitrage","套利（Arbitrage）","套利是利用同一资产在不同市场、不同产品或不同时间点之间的价格差，同时低买高卖、尽量不承担方向风险来赚取差价的交易方式。"],["hedging","对冲（Hedging）","对冲是建立一个与现有持仓方向相反或相关的仓位，用来抵消部分价格波动风险的做法，例如持有现货的同时开合约空单。"],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"没涨没跌也扣钱？带着成本完成最后一关"},"coin":null,"tool":"/funding-rates","cta":false},"hardware-wallet":{"slug":"hardware-wallet","cat":"wallets-security","en":"Hardware wallet","contentLocale":"zh-Hans","term":"硬件钱包（Hardware Wallet）","aka":["硬件钱包","Hardware wallet","冷钱包设备"],"short":"硬件钱包是一种专门保管私钥的小型实体设备，私钥在设备内部生成并签名，从不传到电脑或手机上，是最常用的冷钱包形式。","body":[["硬件钱包外形像 U 盘或小卡片，常见品牌有 Ledger、Trezor 等。初始化时设备会生成一组",["助记词","seed-phrase"],"让你抄写，",["私钥","private-key"],"保存在设备的安全芯片里。转账时，电脑或手机上的钱包软件把交易发给设备，你在设备屏幕上核对地址和金额，按键确认后设备签名再发回去。"],["这样即使电脑感染木马，攻击者也只能看到交易请求，拿不到私钥。但硬件钱包防不住你自己批准的恶意交易：如果在",["钓鱼网站","phishing"],"上确认了一笔无限额授权，设备照样会签。"],"设备本身坏了或丢了并不可怕，只要助记词还在，就能在新设备或其他兼容钱包中恢复资产；反过来，助记词泄露，设备再安全也没用。"],"example":["假设你花 80 美元买了一台硬件钱包，用来存放价值 15,000 ",["USDT","usdt"]," 的资产，保护成本约为资产的 0.5%。某次转账时，电脑上显示的",["收款地址","wallet-address"],"以 0x7a3 开头，而设备屏幕上显示的是 0x9f1 开头，说明电脑端地址可能被木马替换，你应该立刻拒绝签名。"],"mistakes":["从非官方渠道购买，收到的设备附带“已生成好”的助记词卡片。","只看电脑屏幕上的地址，不在硬件钱包屏幕上逐字核对。","把助记词输入到电脑或手机里“备份”，等于把冷钱包变回了热钱包。"],"faq":[{"q":"硬件钱包丢了，币还在吗？","a":"币一直在链上，不在设备里。只要你保存好了助记词，就可以在新设备上恢复；如果设备设置了 PIN 码，捡到的人也很难直接使用。"},{"q":"硬件钱包会被盗吗？","a":"远程窃取私钥非常困难，但助记词泄露、买到被篡改的设备、在钓鱼网站签恶意授权，都可能导致资产被盗。"}],"title":"什么是硬件钱包？原理、用法与注意事项","description":"硬件钱包是什么？了解它如何离线保存私钥和签名、为何要在设备屏幕核对地址、设备丢失怎么办，以及购买时要避开的坑。","related":[["cold-wallet","冷钱包（冷存储）","冷钱包是把私钥保存在不联网环境中的钱包或存储方式，例如硬件钱包和离线生成的纸钱包，主要用于长期、安全地存放大额加密资产。"],["seed-phrase","助记词（Seed Phrase）","助记词是由 12 或 24 个英文单词组成的钱包备份，可以推导出钱包里的全部私钥，谁拿到助记词，谁就能控制这个钱包里的所有资产。"],["private-key","私钥（Private Key）","私钥是一串只有持有人知道的随机数字，用来对交易进行数字签名，证明你有权动用某个地址里的资产，私钥泄露就等于资产失控。"],["address-poisoning","地址投毒（Address Poisoning）","地址投毒是一种诈骗手法，骗子生成一个首尾字符与你常用地址相同的假地址，向你发送小额或零额转账，让它混进你的交易记录，等你复制错地址。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"币到底在哪：交易所和钱包有什么不同？"},"coin":null,"tool":null,"cta":false},"governance-token":{"slug":"governance-token","cat":"defi","en":"Governance token","contentLocale":"zh-Hans","term":"治理代币（Governance Token）","aka":["治理代币","治理币","Governance token"],"short":"治理代币是赋予持有人对协议或 DAO 提案投票权的代币，例如 UNI、AAVE，持有越多投票权越大，但不一定代表能分享协议收入。","body":[["协议常通过",["空投","airdrop"],"、",["流动性挖矿","yield-farming"],"或公开销售发放治理代币，让用户参与决定协议参数、资金使用和升级方向。投票权一般按持币量计算，有的协议还允许委托给代表投票。"],["治理代币的价值来源经常被讨论：如果只有投票权、没有收入分配或其他用途，它的价格更多取决于市场预期和供需。一些协议后来通过投票开启了手续费分配、回购或",["质押","staking"],"奖励，但这需要逐一了解，不能默认存在。"],"评估治理代币时可以看：总量和解锁计划、团队与投资人持有比例、投票是否被少数地址控制，以及代币是否有实际用途。"],"example":"假设某协议治理代币总量 10 亿枚，团队和投资人持有 40%，即 4 亿枚，分 4 年线性解锁，平均每月约 833 万枚进入流通。你持有 1 万枚，只占总量的 0.001%，对投票结果几乎没有影响；而每月的解锁量可能对价格形成持续的卖压。","mistakes":["把治理代币等同于公司股票，以为自动享有分红。","忽视解锁计划，在大额解锁前重仓买入。","为了领治理代币空投，连接来源不明的网站签名。"],"faq":[{"q":"治理代币有什么用？","a":"主要用于对协议提案投票，部分代币还可以质押、抵押或获得协议收入分配，具体取决于各协议的设计和治理结果。"},{"q":"治理代币和平台币有什么区别？","a":"平台币通常由中心化交易所发行，用于手续费折扣等权益；治理代币一般属于 DeFi 协议或 DAO，核心功能是链上治理投票。"}],"title":"什么是治理代币？投票权、价值与解锁","description":"治理代币是什么意思？了解 UNI、AAVE 等治理代币的投票机制、价值来源与常见争议，以及评估治理代币时要看的解锁和持币分布。","related":[["dao","DAO（去中心化自治组织）","DAO（去中心化自治组织）是通过智能合约和代币投票来管理资金与决策的组织形式，成员按持有的治理代币对提案投票，结果由链上规则或多签执行。"],["tokenomics","代币经济学（Tokenomics）","代币经济学是指一个代币的供应量、分配比例、解锁节奏、用途和销毁机制等设计，决定了代币未来的供需结构。"],["airdrop","空投（Airdrop）","空投是项目方免费向符合条件的钱包地址或用户发放代币的方式，常用于奖励早期用户、分散持币和推广项目。"],["coin-vs-token","币和代币的区别（Coin vs Token）","币（Coin）通常指一条区块链自己的原生资产，如 BTC、ETH；代币（Token）则是基于已有区块链的智能合约发行的资产，如以太坊上的 USDT。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"usdt":{"slug":"usdt","cat":"stablecoins","en":"USDT (Tether)","contentLocale":"zh-Hans","term":"USDT（泰达币）","aka":["USDT","泰达币","Tether","U"],"short":"USDT（泰达币）是由 Tether 公司发行、设计为与美元 1:1 挂钩的稳定币，也是市值和交易量最大的稳定币之一，大多数交易所的现货和合约都以它计价。","body":[["Tether 表示每枚 USDT 由现金、短期美国国债等储备资产支持，并定期发布储备鉴证报告。USDT 发行在多条",["区块链","blockchain"],"上，常见的有",["以太坊","ethereum"],"（ERC20）、波场（TRC20）、BNB 链、Solana、TON 等。"],["在",["交易所","centralized-exchange"],"，USDT 是主要计价单位：",["BTC","bitcoin"],"/USDT、ETH/USDT ",["交易对","trading-pair"],"，以及 U 本位合约都以它结算。很多人通过 ",["C2C","p2p-trading"],"/P2P 用本地法币买卖 USDT，再用它交易其他币。"],"需要注意的几点：充提时一定要选对网络；USDT 是公司发行的资产，发行方可以冻结涉及违法活动的地址；在欧盟等地区，受 MiCA 影响，部分平台对 USDT 的支持有所调整，以平台公告为准。"],"example":"假设你在 C2C 市场用人民币买入 1,000 USDT，打算转到另一家交易所。A 交易所提供 TRC20 和 ERC20 两种网络，提币手续费分别显示为 1 USDT 和 4 USDT。你确认目标交易所支持 TRC20 后选择它，到账 999 USDT；如果选 ERC20，到账 996 USDT，多花 3 USDT。","mistakes":["把 TRC20 的 USDT 提到只支持 ERC20 的地址。","C2C 交易时脱离平台私下付款，或接受来路不明的资金，导致银行卡被冻结。","以为 USDT 等同于美元存款，不了解发行方和储备风险。"],"faq":[{"q":"USDT 是美元吗？","a":"不是。USDT 是挂钩美元的加密代币，价值依赖于 Tether 的储备和赎回能力，没有政府或银行存款保险。"},{"q":"USDT 选 TRC20 还是 ERC20？","a":"关键是接收方支持哪个网络。在双方都支持的前提下，TRC20 等网络手续费通常较低，ERC20 的 Gas 费一般较高。"}],"title":"USDT 是什么？泰达币的原理、网络与风险","description":"USDT 泰达币是什么？了解 Tether 发行的 USDT 如何与美元挂钩、TRC20 与 ERC20 等网络的区别，以及 C2C 买卖和充提时的注意事项。","related":[["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["usdc","USDC（美元币）","USDC 是由 Circle 公司发行、与美元 1:1 挂钩的稳定币，储备主要为现金和短期美国国债，以储备披露较透明著称，在 DeFi 和合规场景中使用广泛。"],["blockchain-network","充提币网络（链的选择）","充提币网络是指充币或提币时选择的区块链，例如 USDT 可以走 TRC20、ERC20 或 BEP20 等不同网络，发送方和接收方必须选择同一条链。"],["depeg","脱锚（Depeg）","脱锚是指稳定币或锚定类资产的市场价格明显偏离它承诺跟随的价值，例如本应等于1美元的稳定币跌到0.95美元或涨到1.03美元。"],["p2p-trading","P2P交易（C2C交易）","P2P交易（币圈常称C2C）是指用户之间在交易所提供的撮合平台上直接买卖加密资产，买方通过银行转账等方式付款给卖方，平台托管卖方的币作为担保。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT是美元吗？为什么买币常见它？"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"synthetic-dollar":{"slug":"synthetic-dollar","cat":"stablecoins","en":"Synthetic dollar (delta-neutral stablecoin)","contentLocale":"zh-Hans","term":"合成美元（Synthetic dollar）","aka":["Delta中性稳定币","合成美元稳定币","USDe"],"short":"合成美元是一种通过持有现货加密资产、同时在永续合约上开等额空单实现Delta中性，从而让价值稳定在约1美元的稳定币，Ethena的USDe是代表。","body":[["传统",["稳定币","stablecoin"],"靠银行存款和国债做储备，合成美元则用",["对冲","hedging"],"来“制造”美元价值：协议持有1美元的ETH或BTC现货，再开1美元的空头",["永续合约","perpetual-futures"],"。币价上涨时现货赚、空单亏；币价下跌时现货亏、空单赚，两边相互抵消，总价值保持在1美元附近，这就是Delta中性。"],["它的收益主要来自永续合约的",["资金费率","funding-rate"],"。",["牛市","bull-market"],"里多头往往付费给空头，资金费率为正，协议的空单就能持续收钱，再加上",["质押","staking"],"类抵押品的收益，因此合成美元常被拿来做收益产品。"],"风险同样来自这里：资金费率长时间为负时，空单要付钱；协议依赖中心化交易所开空，面临交易所托管和对手方风险；极端行情下现货和合约价格短暂偏离，也可能造成脱锚。收益不是固定利息，会随市场变化。"],"example":"假设ETH价格为3,000美元，协议用3,000美元买入1个ETH，同时开1个ETH的空头永续合约。ETH跌到2,400美元时，现货亏600美元，空单赚600美元，总价值仍约3,000美元。如果资金费率是每8小时0.01%，3,000美元仓位每次收0.3美元，一天三次共0.9美元；若资金费率变成每8小时负0.02%，一天就要支付1.8美元。","mistakes":["把合成美元的收益当成银行利息，忽视资金费率转负时收益会下降甚至为负。","以为Delta中性就完全没有风险，忽略了交易所托管和极端行情下的脱锚风险。","只看年化数字，不看收益是来自资金费率、质押收益还是额外的激励。"],"faq":[{"q":"合成美元和USDT有什么不同？","a":"USDT以现金和国债等资产作储备，合成美元则用现货加空头永续合约的对冲组合维持价值，收益和风险都与资金费率相关。"},{"q":"资金费率为负时合成美元会亏吗？","a":"空单需要支付资金费，协议收益会被侵蚀。通常协议会设立储备基金来弥补，但长时间负费率仍是主要风险之一。"}],"title":"什么是合成美元？Delta中性稳定币原理解析","description":"合成美元如何用现货加永续空单维持1美元？了解Delta中性对冲、资金费率收益来源，以及费率转负和交易所风险。","related":[["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"],["hedging","对冲（Hedging）","对冲是建立一个与现有持仓方向相反或相关的仓位，用来抵消部分价格波动风险的做法，例如持有现货的同时开合约空单。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["depeg","脱锚（Depeg）","脱锚是指稳定币或锚定类资产的市场价格明显偏离它承诺跟随的价值，例如本应等于1美元的稳定币跌到0.95美元或涨到1.03美元。"]],"lesson":null,"coin":{"slug":"ethena-usde","name":"Ethena USDe","symbol":"USDE"},"tool":"/funding-rates","cta":false}});
